import { GooeyNav } from "solen-design/react";

const items = [
  { label: "Home", href: "#" },
  { label: "Work", href: "#" },
  { label: "About", href: "#" },
  { label: "Contact", href: "#" }
];

<GooeyNav
  items={items}
  initialActiveIndex={0}
  theme="light"
  size="md"
  frame={true}
  particleCount={15}
  spread={56}
  animationTime={600}
  timeVariance={300}
  gooeyness={0.5}
